--- 设置界面的显示状态
---@param state boolean
function BattleEndLevel:SetActive(state)
    self.state = state
    self:StopAutoDetectClose()
    local canvasGroup = KTool.GetComponent(self.controller.gameObject, typeof(CanvasGroup))
    canvasGroup:DOFade(state and 1 or 0, 0.2)
    -- canvasGroup.alpha = state and 1 or 0
    canvasGroup.interactable = state
    canvasGroup.blocksRaycasts = state
    -- KTool.SetActive(self.controller.gameObject, state)
    if not state and not isNull(self.onCloseCallback) then
        self.onCloseCallback()
    end
end

--- 打开level界面
---@param playerExpInfo table 玩家经验信息 {newLv = 0, oldLv = 0, newExp = 0, oldExp = 0}
---@param cardExpInfo table 卡牌经验信息 cardExpInfo[i][v.playerCardId] = {lv = v.cardLevel, exp = v.cardExp}
---@param taskInfo table 任务信息
---@param showTpe PanelShowType_ 展示类型(直接展示 or 动画展示)
function BattleEndLevel:ShowLevelPanel(playerExpInfo, cardExpInfo, taskInfo, showTpe)
    self.playerExpInfo = playerExpInfo
    self.cardExpInfo = cardExpInfo
    self.taskInfo = taskInfo

    local noTask = self:IsNullTable(taskInfo)

    if showTpe == PanelShowType.Animate then
        self.Animation_Root:Play(noTask and ExpAnimate or ExpAndTaskAnimate)
        self:AutoDetectClose()
        self:StartSkipDelay(0.3)
    elseif showTpe == PanelShowType.Direct then
        self.Animation_Root:Play(noTask and ExpDefault or ExpAndTaskDefault)
    end

    self:ShowPlayerExpInfo(playerExpInfo, showTpe)
    self:ShowHeadNodeList(cardExpInfo, showTpe)
    if not noTask then
        self:ShowTaskNodeList(taskInfo, showTpe)
    end
end

function BattleEndLevel:StopAnimateShowLevelPanel()
    self:StopAnimateShowPlayerExpInfo()
    self:StopAnimateShowHeadNodeList()
    self:StopAnimateShowTaskNodeList()
    self:StopAutoDetectClose()
    self:StopSkipDelay()
end

--- 重新打开level界面
function BattleEndLevel:ReshowLevelPanel()
    self.Animation_Root:Play(self:IsNullTable(self.taskInfo) and ExpDefault or ExpAndTaskDefault)
    -- 遍历任务节点播放default动画
    for i = 1, #self.cacheLTTaskNode, 1 do
        local lt_taskNode = self.cacheLTTaskNode[i]
        lt_taskNode:ReshowTaskNode()
    end
end
