--- 初始化头像节点信息
---@param cardExpInfo table 卡牌经验信息(cardExpInfo[v.playerCardId] = {lv = v.cardLevel, exp = v.cardExp})
function BattleEndLevel:ShowHeadNodeList(cardExpInfo, showType)
    local teamCardInfo = checkTable(cardExpInfo)
    local wave = UIBattlingCtrlMgr:GetInstance():GetBattleWave(BattleInfo.myCamp)
    local teamData = UIBattlingDataMgr:GetTeamListByCamp(BattleInfo.myCamp, wave)
    local teamId = checkTable(QuestConfMgr:GetInstance():GetQuestVoById(BattleEndMgr.questId)).petLineup
    -- print("[结算] 卡牌", table.dump(teamData), cardExpInfo)
    local isFirstUsed = false
    for i = 1, #teamData, 1 do
        if teamData[i].playerCardId == 0 then
            goto continue
        end
        local playerId = teamData[i].playerId
        if UIBattlingTools.IsMyPlayerId(playerId) then
            local lt_headNode
            local needCreate = isNull(self.cacheLTHeadNode[i])
            if needCreate then
                local headNode
                if isFirstUsed == false then
                    isFirstUsed = true
                    headNode = self.RT_HeadNode
                else
                    headNode = KTool.Instantiate(self.RT_HeadRoot.gameObject, self.RT_HeadNode.gameObject)
                end
                local lb_headNode = GetLuaBehaviour(headNode.gameObject, HeadNodeLuaPath)
                lb_headNode:Init()
                lt_headNode = lb_headNode.Env
            else
                lt_headNode = self.cacheLTHeadNode[i]
                KTool.SetActive(lt_headNode.controller.gameObject, true)
            end
            local index = teamData[i].id    -- 战场id
            local playerCardId = teamData[i].playerCardId
            lt_headNode:ShowHeadNode(index, playerCardId, teamId, teamCardInfo[tostring(playerCardId)], showType)
            -- 缓存
            if needCreate then
                self.cacheLTHeadNode[i] = lt_headNode
            end
        end
        ::continue::
    end

    -- for i = #teamData + 1, #self.cacheLTHeadNode, 1 do
    --     KTool.SetActive(self.cacheLTHeadNode[i].controller.gameObject, false)
    -- end
end

function BattleEndLevel:StopAnimateShowHeadNodeList()
    for k, v in pairs(self.cacheLTHeadNode) do
        local lt_headNode = self.cacheLTHeadNode[k]
        lt_headNode:StopAnimateShowHeadNode()
    end
end
