--- 动画展示任务进度
---@param taskInfo table 任务信息 { [taskId] = { oldProgress = 1, newProgress = 2, }, }
function BattleEndLevel:ShowTaskNodeList(taskInfo, showType)
    KTool.SetActive(self.RT_TaskListView.gameObject, true)
    local taskCount = 0
    for taskId, taskProgress in pairs(taskInfo) do
        taskCount = taskCount + 1
        local lt_taskNode
        local needCreate = IsNull(self.cacheLTTaskNode[taskCount])
        if needCreate then
            local taskNode
            if taskCount == 1 then
                taskNode = self.LB_TaskNode.gameObject
            else
                taskNode = KTool.Instantiate(self.RT_TaskListRoot.gameObject, self.LB_TaskNode.gameObject)
            end
            local lb_taskNode = GetLuaBehaviour(taskNode.gameObject, TaskNodeLuaPath)
            lb_taskNode:Init()
            lt_taskNode = lb_taskNode.Env
        else
            lt_taskNode = self.cacheLTTaskNode[taskCount]
            KTool.SetActive(lt_taskNode.controller.gameObject, true)
        end
        lt_taskNode:ShowTaskNode(taskId, taskProgress, showType)
        -- 缓存
        if needCreate then
            table.insert(self.cacheLTTaskNode, lt_taskNode)
        end
    end

    for i = taskCount + 1, #self.cacheLTTaskNode, 1 do
        KTool.SetActive(self.cacheLTTaskNode[i].controller.gameObject, false)
    end
end

function BattleEndLevel:StopAnimateShowTaskNodeList()
    for i = 1, #self.cacheLTTaskNode, 1 do
        local lt_taskNode = self.cacheLTTaskNode[i]
        lt_taskNode:StopAnimateShowTaskNode()
    end
end
