function BattleEndLevel:RootAnimationCompleted()
    local completed = not self.Animation_Root:IsPlaying(self:IsNullTable(self.taskInfo) and ExpAnimate or ExpAndTaskAnimate)
    -- print("[结算] 主动画 ", completed)
    return completed
end

function BattleEndLevel:HeadNodeAnimateCompleted()
    for k, v in pairs(self.cacheLTHeadNode) do
        local lt_headNode = self.cacheLTHeadNode[k]
        if not isNull(lt_headNode.coGroup.co) then
            -- print("[结算] 卡牌动画 ", false)
            return false
        end
    end
    -- print("[结算] 卡牌动画 ", true)
    return true
end

function BattleEndLevel:TaskNodeAnimateCompleted()
    for i = 1, #self.cacheLTTaskNode, 1 do
        local lt_taskNode = self.cacheLTTaskNode[i]
        if not lt_taskNode:TaskNodeAnimateCompleted() then
            -- print("[结算] 任务动画 ", false)
            return false
        end
    end
    -- print("[结算] 任务动画 ", true)
    return true
end

--- 点击经验界面，点一次跳过动画，再点关闭。如果动画已经播完了，点一次就直接关闭
function BattleEndLevel:OnBGBtnClicked()
    if not self.skipDelayComplete then
        -- print("[结算] 关闭保护 ")
        return
    end

    local canClose = self:DetectCanClose()
    if canClose then
        -- print("[结算] 点击关闭界面 ")
        self:SetActive(false)
    else
        -- print("[结算] 点击跳过动画 ")
        self:StopAnimateShowLevelPanel()
        self:ShowLevelPanel(self.playerExpInfo, self.cardExpInfo, self.taskInfo, PanelShowType.Direct)
        self:StartSkipDelay(0.3)
    end
end

--- 检查动画是否全部播完
function BattleEndLevel:DetectCanClose()
    if not self:RootAnimationCompleted()
    or not isNull(self.coGroupPlayerUpgrade.co)
    or not self:HeadNodeAnimateCompleted()
    or not self:TaskNodeAnimateCompleted() then
        return false
    else
        return true
    end
end

--- 自动关闭的检测
function BattleEndLevel:AutoDetectClose()
    self.coAutoDetectClose = cs_coroutine.start(function()
        -- cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        while not self:DetectCanClose() do
            cs_coroutine.yield_return(Yielders.EndOfFrame)
        end
        -- print("[结算] 自动关闭 等待2s")
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
        -- print("[结算] 自动关闭")
        self:SetActive(false)
        self.coAutoDetectClose = nil
    end)
end

--- 停止自动的检测
function BattleEndLevel:StopAutoDetectClose()
    if not isNull(self.coAutoDetectClose) then
        cs_coroutine.stop(self.coAutoDetectClose)
        self.coAutoDetectClose = nil
    end
end

function BattleEndLevel:GetPlayerNextLevelExpData(fromLv)
    return CardConfMgr:GetInstance():GetPlayerExpByLevelId(fromLv + 1, 1)
end

function BattleEndLevel:IsNullTable(t)
    return isNull(t) or (table.count(t) == 0)
end

--- 可以点击跳过的保护时间
---@param time any
function BattleEndLevel:StartSkipDelay(time)
    self.coSkipDelay = cs_coroutine.start(function()
        self.skipDelayComplete = false
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(time))
        self.skipDelayComplete = true
        self.coSkipDelay = nil
    end)
end

--- 停止保护计时
function BattleEndLevel:StopSkipDelay()
    if not isNull(self.coSkipDelay) then
        cs_coroutine.stop(self.coSkipDelay)
        self.coSkipDelay = nil
    end
end
